<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\DanceCupScoringService;
Auth::requirePermission('competitors.view');$pdo=Database::connection();$notice='';$error='';
$tableExists=static function(string $table)use($pdo):bool{try{$q=$pdo->prepare('SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:table');$q->execute(['table'=>$table]);return (int)$q->fetchColumn()>0;}catch(Throwable){return false;}};
$columnExists=static function(string $table,string $column)use($pdo):bool{try{$q=$pdo->prepare('SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:table AND COLUMN_NAME=:column');$q->execute(['table'=>$table,'column'=>$column]);return (int)$q->fetchColumn()>0;}catch(Throwable){return false;}};
$profilesReady=$tableExists('bdc_competitor_dance_cup_profiles');$historyReady=$tableExists('bdc_dance_cup_result_history');$approvalReady=$columnExists('bdc_dance_cup_competitions','submitted_at');$genderReady=$columnExists('bdc_competitors','gender');
if(!$profilesReady){http_response_code(200);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dance Cup Participants | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=442" rel="stylesheet"><style>body{margin:0;background:#eef2f7;font-family:Arial,sans-serif;color:#172033}.dc-safe{max-width:1100px;margin:40px auto;padding:20px}.dc-safe-card{padding:28px;border:1px solid #d7dfe9;border-radius:16px;background:#fff;box-shadow:0 10px 30px rgba(16,32,59,.1)}.dc-safe a{display:inline-block;margin-top:16px;padding:11px 16px;border-radius:9px;background:#17243b;color:#fff;text-decoration:none;font-weight:700}</style></head><body><main class="dc-safe"><section class="dc-safe-card"><h1>Dance Cup Participants</h1><p>The participant dashboard is temporarily unavailable because its database migration has not completed.</p><p><strong>No participant or scoring data was deleted.</strong> Deploy the current migration and reopen this page.</p><a href="./">Back to Dance Cup</a> <a href="../">Admin Dashboard</a></section></main></body></html><?php exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!$historyReady||!$approvalReady)throw new RuntimeException('Dance Cup result approval setup is incomplete. Deploy the current database migration first.');if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');if(!Auth::isSuperAdmin())throw new RuntimeException('Only a Super Admin can approve and publish Dance Cup results.');$competitionId=(int)($_POST['competition_id']??0);$pdo->beginTransaction();DanceCupScoringService::approveResults($pdo,$competitionId,(int)(Auth::user()['id']??0),false,trim((string)($_POST['approval_notes']??''))?:null);$pdo->commit();$notice='Dance Cup result approved and published.';}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();$error=$exception->getMessage();}}
$q=trim((string)($_GET['q']??''));$style=(string)($_GET['style']??'');$entry=(string)($_GET['entry']??'');$level=(string)($_GET['level']??'');$gender=(string)($_GET['gender']??'');$status=(string)($_GET['status']??'active');$page=max(1,(int)($_GET['page']??1));$perPage=in_array((int)($_GET['per_page']??50),[25,50,100,200],true)?(int)$_GET['per_page']:50;
$where=['1=1'];$params=[];
if($q!==''){$where[]='(c.exact_name LIKE :name OR c.bdc_id LIKE :bdc OR c.instagram LIKE :instagram OR p.partner_or_team_name LIKE :partner)';$like='%'.$q.'%';$params+=['name'=>$like,'bdc'=>$like,'instagram'=>$like,'partner'=>$like];}
foreach(['style'=>['p.dance_style',['salsa','bachata','cha_cha','other']],'entry'=>['p.entry_type',['solo','couple','duo','pro_am','team']],'level'=>['p.competition_level',['open','amateur','intermediate','professional','pro_am']],'gender'=>['c.gender',['male','female','non_binary','prefer_not_to_say']],'status'=>['p.status',['active','archived']]] as $key=>[$column,$allowed]){if($key==='gender'&&!$genderReady)continue;if(in_array($$key,$allowed,true)){$where[]=$column.'=:'.$key;$params[$key]=$$key;}}
$rows=[];$total=0;$offset=0;$summary=['profiles'=>0,'participants'=>0,'published'=>0,'winners'=>0];$pendingApprovals=[];
try{$whereSql=implode(' AND ',$where);$count=$pdo->prepare("SELECT COUNT(*) FROM bdc_competitor_dance_cup_profiles p JOIN bdc_competitors c ON c.id=p.competitor_id WHERE {$whereSql}");$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$historySelect=$historyReady?"COALESCE(h.events_entered,0) events_entered,COALESCE(h.wins,0) wins,COALESCE(h.podiums,0) podiums,h.latest_placement,h.latest_event":"0 events_entered,0 wins,0 podiums,NULL latest_placement,NULL latest_event";
$historyJoin=$historyReady?"LEFT JOIN (SELECT competitor_id,COUNT(DISTINCT event_id) events_entered,SUM(placement=1) wins,SUM(placement<=3) podiums,SUBSTRING_INDEX(GROUP_CONCAT(placement ORDER BY approved_at DESC),',',1) latest_placement,SUBSTRING_INDEX(GROUP_CONCAT(event_id ORDER BY approved_at DESC),',',1) latest_event FROM bdc_dance_cup_result_history WHERE competitor_id IS NOT NULL GROUP BY competitor_id) h ON h.competitor_id=c.id":"";
$genderSelect=$genderReady?'c.gender':'NULL gender';$sql="SELECT p.*,c.bdc_id,c.exact_name,c.instagram,c.country,{$genderSelect},c.photo_url,{$historySelect} FROM bdc_competitor_dance_cup_profiles p JOIN bdc_competitors c ON c.id=p.competitor_id {$historyJoin} WHERE {$whereSql} ORDER BY c.exact_name,p.dance_style,p.entry_type,p.competition_level LIMIT :limit OFFSET :offset";$stmt=$pdo->prepare($sql);foreach($params as $key=>$value)$stmt->bindValue(':'.$key,$value);$stmt->bindValue(':limit',$perPage,PDO::PARAM_INT);$stmt->bindValue(':offset',$offset,PDO::PARAM_INT);$stmt->execute();$rows=$stmt->fetchAll();
$summary=['profiles'=>(int)$pdo->query("SELECT COUNT(*) FROM bdc_competitor_dance_cup_profiles WHERE status='active'")->fetchColumn(),'participants'=>(int)$pdo->query("SELECT COUNT(DISTINCT competitor_id) FROM bdc_competitor_dance_cup_profiles WHERE status='active'")->fetchColumn(),'published'=>$historyReady?(int)$pdo->query('SELECT COUNT(*) FROM bdc_dance_cup_result_history')->fetchColumn():0,'winners'=>$historyReady?(int)$pdo->query('SELECT COUNT(*) FROM bdc_dance_cup_result_history WHERE placement=1')->fetchColumn():0];
$pendingApprovals=[];if(Auth::isSuperAdmin()&&$approvalReady)$pendingApprovals=$pdo->query("SELECT c.id,c.category_name,c.dance_style,c.entry_type,c.competition_level,c.submitted_at,e.name event_name FROM bdc_dance_cup_competitions c JOIN bdc_dance_cup_events e ON e.id=c.event_id WHERE c.status='pending_approval' ORDER BY c.submitted_at,c.id")->fetchAll();
}catch(Throwable $exception){$error='Dance Cup participant data could not be loaded: '.$exception->getMessage();$historyReady=false;$approvalReady=false;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dance Cup Participants | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=441" rel="stylesheet"><script defer src="../../public/assets/js/bdc-theme.js?v=420"></script><style>.dc-photo{width:54px;height:64px;object-fit:cover;border-radius:9px}.summary-card{border:0;border-radius:16px}.summary-card strong{font-size:1.8rem}.profile-tags{display:flex;gap:.35rem;flex-wrap:wrap}</style></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="./">BDC Dance Cup</a><div class="d-flex gap-2"><a class="btn btn-outline-light btn-sm" href="workflow.php?workflow=automatic">Scoring</a><a class="btn btn-light btn-sm" href="../">Dashboard</a></div></div></nav><main class="container-fluid py-4" style="max-width:1650px"><div class="d-flex justify-content-between align-items-start flex-wrap gap-2 mb-3"><div><h1 class="h3 mb-1">Dance Cup Participant Management</h1><p class="text-muted mb-0">Approved reusable profiles and Super Admin-approved competition history.</p></div></div><?php if(!$historyReady||!$approvalReady):?><div class="alert alert-warning">Participant profiles are available. Published Dance Cup history will appear after the current database migration completes.</div><?php endif;?><div class="row g-3 mb-4"><?php foreach(['All Participants'=>$summary['participants'],'Active Profiles'=>$summary['profiles'],'Published Results'=>$summary['published'],'Winning Results'=>$summary['winners']] as $label=>$value):?><div class="col-6 col-lg-3"><section class="card summary-card shadow-sm h-100"><div class="card-body"><span class="text-muted small"><?=e($label)?></span><strong class="d-block"><?=$value?></strong></div></section></div><?php endforeach;?></div><form class="card border-0 shadow-sm mb-4"><div class="card-body"><div class="row g-2"><div class="col-lg-4"><label class="form-label small">Search</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Name, BDC ID, Instagram, partner or team"></div><?php foreach(['style'=>['Dance Style',[''=>'All styles','salsa'=>'Salsa','bachata'=>'Bachata','cha_cha'=>'Cha Cha','other'=>'Other']],'entry'=>['Entry Type',[''=>'All entry types','solo'=>'Solo','couple'=>'Couple','duo'=>'Duo','pro_am'=>'Pro-Am','team'=>'Team']],'level'=>['Level',[''=>'All levels','open'=>'Open','amateur'=>'Amateur','intermediate'=>'Intermediate','professional'=>'Professional','pro_am'=>'Pro-Am']],'gender'=>['Gender',[''=>'All genders','female'=>'Female','male'=>'Male','non_binary'=>'Non-binary','prefer_not_to_say'=>'Prefer not to say']]] as $name=>[$label,$options]):?><div class="col-6 col-lg-2"><label class="form-label small"><?=e($label)?></label><select class="form-select" name="<?=$name?>" <?=($name==='gender'&&!$genderReady)?'disabled':''?>><?php foreach($options as $value=>$text):?><option value="<?=e($value)?>" <?=($$name===$value)?'selected':''?>><?=e($text)?></option><?php endforeach;?></select></div><?php endforeach;?><div class="col-12"><button class="btn btn-dark">Apply Filters</button> <a class="btn btn-outline-secondary" href="participants.php">Reset</a></div></div></div></form><p class="text-muted">Showing <?=$total?($offset+1):0?> to <?=min($offset+$perPage,$total)?> of <?=$total?> profiles</p><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Photo</th><th>BDC ID</th><th>Participant</th><th>Country / Gender</th><th>Dance Cup Profile</th><th>Partner / Team</th><th>Career</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><img class="dc-photo" src="<?=e($row['photo_url']?:url('public/assets/img/default-competitor.svg'))?>" alt=""></td><td><a href="../competitors/edit.php?id=<?=(int)$row['competitor_id']?>"><?=e($row['bdc_id'])?></a></td><td><strong><?=e($row['exact_name'])?></strong><small class="d-block text-muted"><?=e($row['instagram']?:'—')?></small></td><td><?=e($row['country']?:'—')?><small class="d-block text-muted"><?=e(ucwords(str_replace('_',' ',$row['gender']?:'unknown')))?></small></td><td><div class="profile-tags"><span class="badge text-bg-primary"><?=e(ucwords(str_replace('_',' ',$row['dance_style'])))?></span><span class="badge text-bg-dark"><?=e(ucwords(str_replace('_',' ',$row['entry_type'])))?></span><span class="badge text-bg-light border"><?=e(ucwords(str_replace('_',' ',$row['competition_level'])))?></span></div></td><td><?=e($row['partner_or_team_name']?:'—')?><?=$row['team_size']?'<small class="d-block text-muted">'.(int)$row['team_size'].' dancers</small>':''?></td><td><strong><?=e((string)$row['events_entered'])?> events</strong><small class="d-block text-muted"><?=e((string)$row['wins'])?> wins · <?=e((string)$row['podiums'])?> podiums</small></td><td><span class="badge text-bg-<?=$row['status']==='active'?'success':'secondary'?>"><?=e(ucfirst($row['status']))?></span></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="text-center text-muted py-5">No Dance Cup participant profiles match these filters.</td></tr><?php endif;?></tbody></table></div></div></main></body></html>
